<?php
require_once dirname(__DIR__).'/includes/auth.php';
$u=require_role('administrator');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;
 $q=db()->prepare("SELECT u.id,u.account_status FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=? AND r.name='student'");$q->execute([$id]);$student=$q->fetch();
 if(!$student)$error='Student account not found.';else{$next=$student['account_status']==='active'?'inactive':'active';db()->prepare('UPDATE users SET account_status=? WHERE id=?')->execute([$next,$id]);audit('student_status_changed','user',$id,'Administrator set student account to '.$next);flash('success','Student account status updated.');redirect('admin/students.php');}
}
$search=trim((string)($_GET['q']??''));$department=filter_input(INPUT_GET,'department',FILTER_VALIDATE_INT)?:0;$status=(string)($_GET['status']??'');
$where=["r.name='student'"];$params=[];
if($search!==''){$where[]='(u.first_name LIKE ? OR u.last_name LIKE ? OR u.matric_number LIKE ?)';$term='%'.$search.'%';array_push($params,$term,$term,$term);}
if($department){$where[]='u.department_id=?';$params[]=$department;}
if(in_array($status,['active','inactive','locked'],true)){$where[]='u.account_status=?';$params[]=$status;}
$sql='SELECT u.id,u.first_name,u.last_name,u.matric_number,u.account_status,u.profile_complete,d.name department,f.name faculty,p.name programme,CONCAT_WS(" ",su.first_name,su.last_name) supervisor,pr.title project_title,pr.status project_status FROM users u JOIN roles r ON r.id=u.role_id LEFT JOIN departments d ON d.id=u.department_id LEFT JOIN faculties f ON f.id=d.faculty_id LEFT JOIN programmes p ON p.id=u.programme_id LEFT JOIN student_supervisors ss ON ss.student_id=u.id AND ss.ended_at IS NULL LEFT JOIN users su ON su.id=ss.supervisor_id LEFT JOIN (SELECT pm.student_id,MAX(pm.project_id) project_id FROM project_members pm GROUP BY pm.student_id) latest ON latest.student_id=u.id LEFT JOIN projects pr ON pr.id=latest.project_id WHERE '.implode(' AND ',$where).' ORDER BY u.created_at DESC LIMIT 500';
$q=db()->prepare($sql);$q->execute($params);$students=$q->fetchAll();
$departments=db()->query('SELECT id,name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle='Student Management';$crumbTrail=['Admin','Students'];require dirname(__DIR__).'/includes/header.php';
?>
<?php if($error): ?><div role="alert" class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<section class="card filter-bar mb-3"><form method="get" class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input class="form-control" id="q" name="q" value="<?= e($search) ?>" placeholder="Search by name or matric number..." aria-label="Search students"></label><div class="filter-selects"><select class="form-select" id="department" name="department" aria-label="Department" data-autosubmit><option value="0">All Departments</option><?php foreach($departments as $d): ?><option value="<?= (int)$d['id'] ?>" <?= $department===(int)$d['id']?'selected':'' ?>><?= e($d['name']) ?></option><?php endforeach; ?></select><select class="form-select" id="status" name="status" aria-label="Account status" data-autosubmit><option value="">All Statuses</option><?php foreach(['active','inactive','locked'] as $s): ?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary btn-sm">Search</button><?php if($search!==''||$department||$status!==''): ?><a class="btn btn-outline-primary btn-sm" href="<?= e(url('admin/students.php')) ?>">Clear</a><?php endif; ?></form></section>
<section class="card p-4"><div class="section-row mb-3"><h2 class="section-heading mb-0">Student Project Registry</h2><span class="text-muted small">Showing <?= count($students) ?> record<?= count($students)===1?'':'s' ?></span></div><div class="table-responsive"><table class="table table-soft align-middle"><thead><tr><th>Student</th><th>Matric number</th><th>Department / programme</th><th>Supervisor</th><th>Project</th><th>Account</th><th class="text-end">Action</th></tr></thead><tbody>
<?php foreach($students as $s): $nm=trim(($s['first_name']??'').' '.($s['last_name']??'')); ?><tr><td><div class="person"><span class="person-avatar"><?= e(ui_initials($nm?:'S')) ?></span><div><strong><?= e($nm?:'Profile not completed') ?></strong><small><?= e($s['faculty']??'—') ?></small></div></div></td><td class="text-muted"><?= e($s['matric_number']??'—') ?></td><td><?= e($s['department']??'—') ?><br><small class="text-muted"><?= e($s['programme']??'Programme pending') ?></small></td><td><?= e($s['supervisor']?:'Not assigned') ?></td><td><?= e($s['project_title']?:'Not registered') ?><?php if($s['project_status']): ?><br><?= ui_pill($s['project_status']) ?><?php endif; ?></td><td><?= status_badge($s['account_status']) ?></td><td class="text-end"><form method="post" data-confirm="Change this student account status?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="user_id" value="<?= (int)$s['id'] ?>"><button class="btn btn-sm btn-outline-primary"><?= $s['account_status']==='active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach; ?>
<?php if(!$students): ?><tr><td colspan="7"><div class="empty-state">No student records match these filters.</div></td></tr><?php endif; ?></tbody></table></div></section>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
